import Foundation
import SwiftData

/// A band the user has added. `id` is generated by the app and is what leaves the phone as
/// `device.id` (docs/API.md); the MAC never does.
@Model
final class Band {
    @Attribute(.unique) var id: UUID
    var name: String
    var model: String
    var mac: String?
    var addedAt: Date
    var lastSyncAt: Date?
    /// How far `AppleHealth.export` has already sent this band's minutes. A default so the
    /// existing store migrates lightweight; nil means nothing has gone to Health yet.
    var lastExportedTo: Date? = nil
    var lastBattery: Int?
    var firmware: String?
    var hardwareModel: String?

    init(name: String, mac: String?) {
        id = UUID()
        self.name = name.trimmingCharacters(in: .whitespaces)
        self.mac = mac
        model = Self.modelCode(for: name)
        addedAt = Date()
    }

    /// Last three hex digits of the MAC; the band advertises its name with them ("HUAWEI Band 6-EF1").
    var macSuffix: String? {
        guard let mac else { return nil }
        let hex = mac.uppercased().filter(\.isHexDigit)
        return hex.count >= 3 ? String(hex.suffix(3)) : nil
    }

    var shortName: String { Self.shortName(name: name, model: model) }
    var displayName: String { Self.displayName(name: name, mac: mac) }

    /// "AA:BB:CC:DD:EE:FF" from whatever the user typed; nil when it is not six bytes.
    static func normalizedMAC(_ text: String) -> String? {
        let hex = text.uppercased().filter(\.isHexDigit)
        guard hex.count == 12 else { return nil }
        return stride(from: 0, to: 12, by: 2).map { i in
            String(hex[hex.index(hex.startIndex, offsetBy: i) ..< hex.index(hex.startIndex, offsetBy: i + 2)])
        }.joined(separator: ":")
    }

    static func modelCode(for name: String) -> String {
        let lower = name.lowercased()
        if lower.contains("band 7") { return "band7" }
        if lower.contains("band 6") { return "band6" }
        return "huawei"
    }

    static func shortName(name: String, model: String) -> String {
        switch model {
        case "band6": return "Band 6"
        case "band7": return "Band 7"
        default:
            let trimmed = name.replacingOccurrences(of: "HUAWEI ", with: "", options: .caseInsensitive)
            return trimmed.split(separator: "-").first.map(String.init) ?? "Band"
        }
    }

    /// "Band 6 (EF1)": the suffix is what the band shows in its own Bluetooth name.
    static func displayName(name: String, mac: String?) -> String {
        let short = shortName(name: name, model: modelCode(for: name))
        let hex = (mac ?? "").uppercased().filter(\.isHexDigit)
        return hex.count >= 3 ? "\(short) (\(hex.suffix(3)))" : short
    }
}

/// One observation from a band. `kind` is `live` or `battery`; unused fields stay 0.
/// `steps` and `calories` in `live` samples are that day's cumulative totals.
@Model
final class Sample {
    var bandID: UUID
    var kind: String
    var ts: Date
    var steps: Int
    var calories: Int
    var heartRate: Int
    var standingHours: Int
    var level: Int
    var pushedToHub: Bool

    init(bandID: UUID, draft: SampleDraft) {
        self.bandID = bandID
        kind = draft.kind
        ts = draft.ts
        steps = draft.steps
        calories = draft.calories
        heartRate = draft.heartRate
        standingHours = draft.standingHours
        level = draft.level
        pushedToHub = false
    }
}

/// A raw activity file from the band, kept as received (CRC-checked) so it can be parsed again
/// as the parsers improve. `fileID` is the 7-byte id in hex.
@Model
final class ActivityBlob {
    var bandID: UUID
    var fileID: String
    var ts: Date
    var type: Int
    var subtype: Int
    var detailType: Int
    var version: Int
    @Attribute(.externalStorage) var data: Data
    var fetchedAt: Date
    var parsedAt: Date?
    var parseNote: String?
    /// ActivityIngest.parserVersion this file was last parsed with; 0 = never. Files below the
    /// current version are parsed again at launch.
    var parserVersion: Int = 0
    /// ParseStatus raw value: pending, parsed, partial, unsupported, error, crc.
    var parseStatus: String = "pending"
    /// Last fetched from the band's "today" list, so it may still have grown since; such a file
    /// is fetched once more when it shows up in the past list (AppModel.hasActivityFile).
    var fetchedFromToday: Bool = false

    init(bandID: UUID, id: ActivityFileID, data: Data) {
        self.bandID = bandID
        fileID = id.hex
        ts = id.ts
        type = Int(id.type)
        subtype = Int(id.subtype)
        detailType = Int(id.detailType)
        version = Int(id.version)
        self.data = data
        fetchedAt = Date()
        parserVersion = 0
        parseStatus = ParseStatus.pending.rawValue
        fetchedFromToday = false
    }

    /// "Daily details v4" style label for diagnostics.
    var kindLabel: String {
        let kind: String
        switch (type, subtype, detailType) {
        case (0, 0, 0): kind = String(localized: "Daily details", comment: "Activity file kind")
        case (0, 0, 1): kind = String(localized: "Daily summary", comment: "Activity file kind")
        case (0, 3, _): kind = String(localized: "Sleep stages", comment: "Activity file kind")
        case (0, 6, _): kind = String(localized: "Manual reading", comment: "Activity file kind")
        case (0, 8, _): kind = String(localized: "Sleep", comment: "Activity file kind")
        case (1, _, 1): kind = String(localized: "Workout summary", comment: "Activity file kind")
        case (1, _, 2): kind = String(localized: "Workout GPS", comment: "Activity file kind")
        case (1, _, _): kind = String(localized: "Workout", comment: "Activity file kind")
        default: kind = String(localized: "Unknown \(type)/\(subtype)/\(detailType)", comment: "Activity file kind")
        }
        return "\(kind) v\(version)"
    }
}

/// Webhook target configured on the phone. The secret signs each delivery (HMAC-SHA256).
@Model
final class Webhook {
    @Attribute(.unique) var id: UUID
    var url: String
    var secret: String
    var enabled: Bool
    var createdAt: Date
    var lastStatus: String?
    var lastAt: Date?

    init(url: String, secret: String) {
        id = UUID()
        self.url = url
        self.secret = secret
        enabled = true
        createdAt = Date()
    }
}

/// Plain value produced by a band session before it is stored.
struct SampleDraft: Equatable {
    var kind: String
    var ts: Date
    var steps = 0
    var calories = 0
    var heartRate = 0
    var standingHours = 0
    var level = 0

    static func live(_ stats: BandInfo.LiveStats, at ts: Date = Date()) -> SampleDraft {
        SampleDraft(kind: "live", ts: ts, steps: Int(stats.steps), calories: Int(stats.calories),
                    heartRate: Int(stats.heartRate), standingHours: Int(stats.standingHours))
    }

    static func battery(_ level: Int, at ts: Date = Date()) -> SampleDraft {
        SampleDraft(kind: "battery", ts: ts, level: level)
    }
}
